import axios from "axios";

export const updateUIAfterDelete = (category, imageUrl, setGetSlider, setGetStoredPhotos, setGetGalleryPhoto, setGetLogos) => {
    const updateState = (setter) => {
      setter((prev) => (imageUrl ? prev.filter((img) => img.url !== imageUrl) : []));
    };
  
    if (category === "slider") updateState(setGetSlider);
    if (category === "StoredPhotos") updateState(setGetStoredPhotos);
    if (category === "GalleryPhoto") updateState(setGetGalleryPhoto);
    if (category === "Logos") updateState(setGetLogos);
  };
  
  export const toggleImageStatus = async (category, imageUrl, setLoading, setGetGalleryPhoto, setGetLogos, setGetSlider, setGetStoredPhotos) => {
    setLoading(true);
    try {
      await axios.patch("http://localhost:5000/toggle-photo-status", {
        category,
        url: imageUrl,
      });
  
      setLoading(false);
  
      const updateState = (setter, singleActive) => {
        setter((prev) =>
          prev.map((img) => ({
            ...img,
            isActive: singleActive
              ? img.url === imageUrl // Only one active
              : img.url === imageUrl
              ? !img.isActive // Toggle for multiple active
              : img.isActive, // Keep previous state
          }))
        );
      };
  
      // Allow only one active image for "GalleryPhoto" and "Logos"
      if (category === "GalleryPhoto") updateState(setGetGalleryPhoto, true);
      else if (category === "Logos") updateState(setGetLogos, true);
      else {
        // Allow multiple active images for other categories
        if (category === "slider") updateState(setGetSlider);
        if (category === "StoredPhotos") updateState(setGetStoredPhotos);
      }
    } catch (error) {
      setLoading(false);
      console.error("Failed to toggle image status:", error);
    }
  };
